head.b:skin:
/* <Variable name="page.background" description="Page background" type="color" default="#0e1122" value="#0e1122"/><Variable name="page.text" description="Text color" type="color" default="#eee9df" value="#eee9df"/><Variable name="theme.accent" description="Accent color" type="color" default="#e0bd88" value="#e0bd88"/> */
/* Blogger stylesheet compatibility: restore the spacing Blogger's own widget stylesheet removes, and keep post content inside a phone screen. */
h1{margin:.67em 0}h2{margin:.83em 0}h3{margin:1em 0}h4{margin:1.33em 0}h1,h2,h3,h4,a img{position:static}body{padding:0;word-break:normal}.post-body{width:auto;overflow-x:auto}.post-body a[style*='margin-left'],.post-body a[style*='margin-right']{margin-inline:0!important}.post-body .separator,.post-body .tr-caption-container{max-width:100%}.widget .post-body ul,.widget .post-body ol{margin:1em 0;padding:0 0 0 1.4em;line-height:inherit}.widget .post-body li{margin:0 0 .35em;padding:0}.latest-empty{display:none}.single-view{font-size:1rem}.single-view .post-title{overflow-wrap:anywhere}
:root{--bg:$(page.background);--ink:$(page.text);--accent:$(theme.accent);--heading:"Cormorant Garamond",Georgia,serif;--body:"DM Sans",sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 var(--body)}h1,h2,h3{font-family:var(--heading);line-height:1.15}a{color:inherit;text-underline-offset:4px}a:hover{text-decoration-thickness:2px}img{max-width:100%;height:auto}svg{max-width:100%;height:auto}button,input{font:inherit}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid currentColor;outline-offset:5px}a,button,summary{touch-action:manipulation}nav{max-width:100%}p,h1,h2,h3,a{overflow-wrap:anywhere}.skip-link{position:fixed;top:-100px;left:16px;z-index:100;background:var(--ink);color:var(--bg);padding:12px}.skip-link:focus{top:12px}.section,.widget{min-width:0;margin:0;padding:0;line-height:inherit}.latest{max-width:1200px;margin:64px auto;padding:0 24px}.posts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.post-card{min-width:0}.post-title a{text-decoration:none}.post-title a:hover{text-decoration:underline}.post-media{display:block;aspect-ratio:16/10;overflow:hidden;background:color-mix(in srgb,var(--accent) 12%,var(--bg))}.post-media img{width:100%;height:100%;object-fit:cover}.post-art{height:100%;display:grid;place-items:center;font:italic 70px var(--heading);color:var(--accent)}.post-meta{margin-top:18px;font-size:12px}.post-meta a{margin-right:12px}.pager{display:flex;justify-content:space-between;gap:20px;margin-top:40px;padding-top:20px;border-top:1px solid currentColor}.pager a{padding:10px 0}.post-body{max-width:70ch;margin-inline:auto;overflow-wrap:anywhere}.post-body img,.post-body iframe{max-width:100%}.post-body pre,.post-body table{display:block;overflow:auto;max-width:100%}.single-view .latest{max-width:900px}.single-view .section-heading{display:none}.single-view .post-title{font-size:clamp(32px,5vw,62px)}.single-view #comments{margin-top:60px}.empty-state,.error-state{padding:45px 0}.error-state{max-width:900px;margin:auto;padding:70px 24px}.listing-heading{font-size:clamp(28px,5vw,52px)}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.posts-grid{grid-template-columns:1fr}.latest{margin:45px auto}.pager{flex-wrap:wrap}}
html{scroll-behavior:smooth}body{margin:0}a{color:inherit}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid var(--accent);outline-offset:5px}img{max-width:100%}header,footer{position:relative}nav{display:flex;gap:24px;flex-wrap:wrap}nav a{text-decoration:none}.wordmark{text-decoration:none;font-weight:700}.brandline{display:flex;align-items:center;justify-content:space-between;gap:24px}.eyebrow{font-size:12px;letter-spacing:.16em;text-transform:uppercase}.art{display:block;width:100%;height:auto}p{line-height:1.7}.post-title a{text-decoration:none}.post-meta{font-size:11px;letter-spacing:.07em;text-transform:uppercase}.post-excerpt{line-height:1.6}.post-media{display:block;width:100%;aspect-ratio:16/10;object-fit:cover}.section-heading{font-size:30px;margin:0 0 30px}.post-title{font-size:24px;line-height:1.2}.post-card{min-width:0}footer{margin-top:80px}footer p{margin:0}.footerline{display:flex;justify-content:space-between;gap:25px;align-items:center}.page-content,.post-body{max-width:760px;margin:auto}.post-body{line-height:1.8}main>.section-heading,main>.posts-grid{max-width:1200px;margin-left:auto;margin-right:auto}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.brandline,.footerline{align-items:flex-start;flex-direction:column}nav{gap:16px}.section-heading{font-size:26px}.post-title{font-size:22px}main>.section-heading,main>.posts-grid{margin-left:20px;margin-right:20px}}body{background:#0e1122;color:#eee9df;font-family:"DM Sans",sans-serif}header{padding:30px 5vw;border-bottom:1px solid #343749}.wordmark{font-size:17px;letter-spacing:.16em}nav{font-size:12px;color:#c6c3d4}.sky-hero{display:grid;grid-template-columns:1fr 1.05fr;gap:25px;align-items:center;max-width:1400px;margin:auto;padding:80px 5vw 65px;background:radial-gradient(ellipse at 80% 50%,#252339 0,transparent 55%)}.sky-copy h1{font:400 clamp(72px,8.4vw,124px)/.91 "Cormorant Garamond",serif;letter-spacing:-.045em;margin:30px 0}.sky-copy em{font-weight:400;color:#e0bd88}.eyebrow{color:#c9b99c;font-size:10px}.sky-copy p:not(.eyebrow){max-width:370px;color:#b9b7c8;font-size:15px}.sky-link{display:inline-flex;gap:40px;border-bottom:1px solid #e0bd88;padding:16px 0;text-decoration:none;font-size:13px}.sky-link span{transition:transform .2s}.sky-link:hover span{transform:translate(4px,-4px)}.sky-caption{display:block;text-align:center;font:9px monospace;letter-spacing:.13em;color:#aaa7bd}.sky-practice{margin:0 5vw;padding:38px 0 45px;display:grid;grid-template-columns:1.1fr 1fr 1fr 1fr;gap:30px;border-top:1px solid #3b3a4c;border-bottom:1px solid #3b3a4c}.practice-intro h2{font:400 45px/.98 "Cormorant Garamond",serif;margin:15px 0}.sky-number{font:italic 35px "Cormorant Garamond",serif;color:#e0bd88}.sky-practice h3{font-size:15px;font-weight:500}.sky-practice article p{color:#b9b7c8;font-size:12px}.sky-divider{display:flex;justify-content:space-between;align-items:center;margin:60px 5vw 30px;font-size:10px;letter-spacing:.14em;color:#b9b7c8}.section-heading{font:400 50px "Cormorant Garamond",serif;margin:0 5vw 30px}.posts-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:32px;margin:0 5vw}.post-card{border-top:1px solid #655b5b;padding-top:18px}.post-media{aspect-ratio:4/3;background:#262940;filter:saturate(.6);border-radius:50% 50% 0 0}.post-meta{margin-top:18px;color:#c9b99c;font-size:9px}.post-title{font:400 32px/1.1 "Cormorant Garamond",serif}.post-excerpt{font-size:13px;color:#b9b7c8}.sky-lens{margin:90px 5vw 0;text-align:center;background:#171a2e;border:1px solid #35394f;padding:55px 30px}.big-star{color:#e0bd88;font-size:55px}.sky-lens h2{font:400 54px/1.05 "Cormorant Garamond",serif;margin:22px 0}.sky-lens p:not(.eyebrow){max-width:500px;margin:0 auto 25px;font-size:14px;color:#b9b7c8}.sky-lens a{font-size:12px;color:#e0bd88;text-underline-offset:5px}footer{border-top:1px solid #343749;padding:35px 5vw;color:#b9b7c8;font-size:11px}.observatory-wordmark{font:25px "Cormorant Garamond",serif}@media(max-width:700px){.sky-hero{grid-template-columns:1fr;padding-top:50px}.sky-copy h1{font-size:80px}.moon-art{max-width:500px}.sky-practice{grid-template-columns:1fr 1fr;gap:25px}.posts-grid{grid-template-columns:1fr}.sky-lens h2{font-size:39px}.sky-divider span:last-child{display:none}.post-media{aspect-ratio:16/9;border-radius:80px 80px 0 0}}
.latest{max-width:none;margin:55px 0;padding:0}.latest>.section-heading,.latest>.posts-grid{max-width:none}a:hover span,a:focus-visible span{transition:transform .2s}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{animation:none!important;transition:none!important}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto!important}*,*::before,*::after{animation:none!important;transition:none!important}.post-media img{transform:none!important}}@media print{nav,.skip-link,.pager{display:none!important}body{background:white;color:black}}
